"""docs/bench.md: the CratonBench card, generated from the code and the frozen record.

Like the data cards, it is written by ``craton bench cards`` and ``craton check`` fails if the
file drifts from what the code and ``craton/bench/frozen/`` say.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from craton.bench.splits import ERAS, SPLITS, definition
from craton.bench.tasks import CB01_BINS, TASKS, load_frozen

HEADER = (
    "<!-- Generated by `craton bench cards` from craton/bench/. Do not edit by hand:\n"
    "     `craton check` fails if this file drifts from the code. -->\n"
)

ABOUT = {
    "CB-01": (
        "Hide 15% of the measurements in the two held-out eras and ask for each one back. "
        "A quake's time and magnitude type are shown; where it was, how deep and how big are "
        "hidden. A GNSS day shows the station and its site to 0.01°; its east, north and up "
        "are hidden. Every answer is a probability distribution, scored in bits on fixed "
        "bins, like perplexity for a language model. The tide token computed at a hidden "
        "quake is hidden too, because it sits at the quake's epicentre."
    ),
    "CB-02": (
        "A forecast every midnight for the next day: how many quakes in every 0.1° cell and "
        "every 0.1 magnitude bin, knowing only the quakes before midnight. 494 days of the "
        "Amatrice-Visso-Norcia-Campotosto sequence. Models fit only on data before "
        "24 August 2016. Scored by the joint Poisson log-likelihood per M3+ quake, the "
        "CSEP standard; the difference between two models is their information gain."
    ),
    "CB-03": (
        "The same game for 2009, the year of L'Aquila, with models fitted only on data "
        "before 2009. The catalogue before 2005 is in another magnitude type (Md), so "
        "the baselines fit on four years, 2005 to 2008."
    ),
    "CB-04": (
        "Hide every day of 29 GNSS stations from everything, then rebuild their daily "
        "positions from the other stations. A station's series starts from an arbitrary "
        "origin, so each station's mean offset per component is removed before the RMSE."
    ),
}


def _bins() -> list[str]:
    out = ["| Instrument | Channel | Bin width | Edges |", "|---|---|---|---|"]
    for inst, bins in CB01_BINS.items():
        for b in bins:
            edges = "k·w" if not b.offset else f"k·w − {b.offset:g}"
            out.append(f"| `{inst}` | {b.channel} | {b.width:g} | {edges} |")
    return out


def render() -> str:
    frozen: dict[str, Any] = load_frozen() or {}
    lines = [HEADER, "# CratonBench v1", ""]
    lines += [
        "Four tests, frozen before any model exists. A test's data and metric never change; "
        "a better test gets a new ID. Each is fingerprinted: the hash of its definition, its "
        "metric and every test file, and the ratchet refuses a run whose fingerprint differs.",
        "",
        f"Region `{frozen.get('region', '?')}`, data snapshot `{frozen.get('snapshot', '?')}`.",
        "",
        "## What is held out",
        "",
        "| Held out | From | To |",
        "|---|---|---|",
    ]
    for w in ERAS:
        lines.append(f"| {w.name.replace('_', ' ').title()} | {w.start[:10]} | {w.end[:10]} |")
    stations = frozen.get("heldout_stations", [])
    lines += [
        "",
        f"And {len(stations)} GNSS stations, one in ten, chosen by a salted hash among "
        "stations with at least two years of data, three visible neighbours within 50 km, and "
        "no day-to-day jump over "
        f"{definition()['heldout']['max_jump_m']:g} m: "
        + ", ".join(f"`{s}`" for s in stations)
        + ".",
        "",
        "## Training splits",
        "",
        "Cut from the snapshot and written to disk, every file named by its hash. "
        "`craton bench leaks` reads every shard back and fails on a single held-out token.",
        "",
        "| Split | For | Tokens | Left out | Manifest |",
        "|---|---|---|---|---|",
    ]
    for name, spec in SPLITS.items():
        s = frozen.get("splits", {}).get(name, {})
        lines.append(
            f"| `{name}` | {spec.purpose} | {s.get('tokens', 0):,} | {s.get('left_out', 0):,} "
            f"| `{s.get('id', '?')}` |"
        )
    for task_id, task in TASKS.items():
        f = frozen.get("tasks", {}).get(task_id, {})
        better = "lower is better" if task.direction == "lower" else "higher is better"
        lines += [
            "",
            f"## {task_id} · {task.name}",
            "",
            ABOUT.get(task_id, ""),
            "",
            f"- **Metric:** {task.metric} ({better})",
            f"- **Fingerprint:** `{f.get('fingerprint', '?')[:16]}`",
        ]
        summary = f.get("summary", {})
        if summary:
            parts = []
            for k, v in summary.items():
                if isinstance(v, dict):
                    v = ", ".join(f"{a} {b:,}" for a, b in v.items())
                elif isinstance(v, int | float):
                    v = f"{v:,}"
                parts.append(f"{k.replace('_', ' ')} {v}")
            lines.append("- **Test data:** " + " · ".join(parts))
        if task_id == "CB-01":
            lines += ["", *_bins()]
    lines += [
        "",
        "## Add a method",
        "",
        "Implement the task's protocol (`MaskedPredictor`, `Forecaster` or `GapFiller` in "
        "`craton/bench/tasks.py`), register it with `register_method`, and run "
        "`craton bench run NAME`. The run lands in `results/pending/`; `craton ratchet "
        "--accept` puts it on the scoreboard if nothing got worse.",
        "",
    ]
    return "\n".join(lines)


def path(root: Path) -> Path:
    return root / "docs" / "bench.md"


def write(root: Path) -> Path:
    out = path(root)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render(), encoding="utf-8", newline="\n")
    return out


def drift_problem(root: Path) -> str | None:
    out = path(root)
    if not out.is_file():
        return "docs/bench.md is missing; run `craton bench cards`"
    if out.read_text(encoding="utf-8").replace("\r\n", "\n") != render():
        return "docs/bench.md is out of date; run `craton bench cards`"
    return None
